    true ? (void)0 : ::logging::VoidifyStream((::logging::CheckOpValueStr(type_), ::logging::CheckOpValueStr(EventType::kGesturePinchUpdate), (type_)==(EventType::kGesturePinchUpdate))) & (*::logging::g_swallow_stream);
